/**
 [EN] How the icon and the title are arranged: side by side (a tag, a chip) or the icon above the title (a tab, a
      placeholder, an empty state).
 [CN] 图标与标题的排列：左右并排（标签、chip）或图标在标题上方（Tab、占位图、空状态）。
 */
@objc public enum CYLAnimatedItemAxis: Int {
    /** [EN] The icon before the title (default). [CN] 图标在标题前（默认）。 */
    case horizontal = 0
    /** [EN] The icon above the title. [CN] 图标在标题上方。 */
    case vertical
}

/**
 [EN] Where the content group sits: centered (default) or against the leading edge.
 [CN] 内容组的位置：居中（默认）或靠前缘。
 */
@objc public enum CYLAnimatedItemAlignment: Int {
    /** [EN] Centered (default). [CN] 居中（默认）。 */
    case center = 0
    /** [EN] Against the leading edge. [CN] 靠前缘。 */
    case leading
}

/**
 [EN] Where the accessory icon goes: before the content, after it (default), or on the icon's top trailing corner (like
      a badge or a close button).
 [CN] 附加图标的位置：内容之前、内容之后（默认），或图标右上角（像角标或关闭按钮）。
 */
@objc public enum CYLAnimatedItemAccessoryPlacement: Int {
    /** [EN] Before the content. [CN] 内容之前。 */
    case leading = 0
    /** [EN] After the content (default). [CN] 内容之后（默认）。 */
    case trailing
    /** [EN] On the icon's top trailing corner. [CN] 图标右上角。 */
    case topTrailing
}

/**
 [EN] The look of the control: the plain animated icon + title (default), or a countdown button, e.g. for "Get the SMS
      code" (see `CYLAnimatedItemView.startCountdown()`).
 [CN] 控件的样式：普通的动效 icon + title（默认），或倒计时按钮，例如「获取验证码」（见 `CYLAnimatedItemView.startCountdown()`）。
 */
@objc public enum CYLAnimatedItemStyle: Int {
    /** [EN] The plain animated icon + title (default). [CN] 普通的动效 icon + title（默认）。 */
    case plain = 0
    /**
     [EN] A bordered countdown button: idle title, then "N seconds left" until the time is up, then a finished title.
     [CN] 带边框的倒计时按钮：先显示待机标题，再显示「还剩 N 秒」直到时间到，最后显示结束标题。
     */
    case countdown
}

/**
 [EN] Where a countdown is. [CN] 倒计时所处的阶段。
 */
@objc public enum CYLAnimatedItemCountdownState: Int {
    /** [EN] Not started: the idle title shows and a tap can start it. [CN] 未开始：显示待机标题，点击可以开始。 */
    case idle = 0
    /** [EN] Counting down: the control is disabled. [CN] 倒计时中：控件不可用。 */
    case running
    /** [EN] The time is up: the finished title shows and a tap can start it again. [CN] 时间到：显示结束标题，点击可以再次开始。 */
    case finished
}

/**
 [EN] What the item shows. `CYLAnimatedItemView` stores every property; a subclass may compute them instead.
 [CN] 条目显示的内容。`CYLAnimatedItemView` 保存所有属性；子类也可以自行计算。
 */
@objc public protocol CYLAnimatedItemContent: NSObjectProtocol {
    /** [EN] The title, or nil for an icon-only item. [CN] 标题；只有图标时为 nil。 */
    var title: String? { get set }
    /** [EN] The static icon, shown until an animation is ready and whenever there is none. [CN] 静态图标：动画就绪前以及没有动画时显示。 */
    var image: UIImage? { get set }
    /** [EN] The icon while selected; nil uses `image`. [CN] 选中时的图标；为 nil 时使用 `image`。 */
    var selectedImage: UIImage? { get set }
}

/**
 [EN] The animated icon. Any file of the animation engine plays (Lottie, PAG, Rive, GIF, SVGA and every animator
      registered later in `CYLTabBarItemAnimatorRegistry`): a new animation type is a new animator there, nothing else.
      The examples' Play all / speed / loop controls map to `restartAnimation()`, `animationSpeed` and `animationLoops`.
 [CN] 动效图标。动画引擎支持的文件都能播放（Lottie、PAG、Rive、GIF、SVGA，以及以后在 `CYLTabBarItemAnimatorRegistry` 中注册的 animator）：
      新增动画类型只需新增一个 animator，其他地方都不用改。示例中的「全部播放」/ 倍速 / 循环分别对应 `restartAnimation()`、`animationSpeed`
      与 `animationLoops`。
 */
@objc public protocol CYLAnimatedItemAnimating: NSObjectProtocol {
    /** [EN] The animation file (a file URL or a remote URL, with options); nil removes the animation. [CN] 动画文件（本地或远程 URL，可带选项）；nil 移除动画。 */
    var animationURL: URL? { get set }
    /** [EN] Speed, 1 by default; 0 or less keeps the file's own speed. [CN] 速度，默认 1；0 或负数使用文件自身的速度。 */
    var animationSpeed: CGFloat { get set }
    /** [EN] Whether the animation loops. [CN] 动画是否循环播放。 */
    var animationLoops: Bool { get set }
    /** [EN] The progress shown while not playing (0 the first frame, 1 the last). [CN] 未播放时显示的进度（0 为首帧，1 为末帧）。 */
    var animationRestingProgress: CGFloat { get set }
    /** [EN] Whether the animation view is in place. [CN] 动画视图是否已就绪。 */
    @objc(animationReady) var isAnimationReady: Bool { @objc(isAnimationReady) get }
    /** [EN] Plays from the current progress. [CN] 从当前进度开始播放。 */
    func playAnimation()
    /** [EN] Plays from progress 0 (the examples' "Play all"). [CN] 从进度 0 开始播放（示例中的「全部播放」）。 */
    func restartAnimation()
    /** [EN] Stops and shows the resting progress. [CN] 停止并显示静止进度。 */
    func stopAnimation()
    /** [EN] Shows the last frame without playing. [CN] 不播放，直接显示最后一帧。 */
    func showAnimationLastFrame()
}

/**
 [EN] The delegate of an item's gestures. Every method is optional.
 [CN] 条目手势的代理。所有方法都是可选的。
 */
@objc public protocol CYLAnimatedItemViewDelegate: NSObjectProtocol {
    /** [EN] The item was tapped (not on its accessory). `UIControlEventTouchUpInside` is sent as well. [CN] 点击了条目（不是附加图标）。同时也会发送 `UIControlEventTouchUpInside`。 */
    @objc optional func animatedItemViewDidTap(_ itemView: CYLAnimatedItemView)
    /** [EN] The item was long-pressed. [CN] 长按了条目。 */
    @objc optional func animatedItemViewDidLongPress(_ itemView: CYLAnimatedItemView)
    /** [EN] The accessory icon was tapped. [CN] 点击了附加图标。 */
    @objc optional func animatedItemViewDidTapAccessory(_ itemView: CYLAnimatedItemView)
    /** [EN] The countdown started. [CN] 倒计时开始。 */
    @objc optional func animatedItemViewDidStartCountdown(_ itemView: CYLAnimatedItemView)
    /** [EN] The whole seconds left changed, once per second. [CN] 剩余整秒数变化，每秒一次。 */
    @objc(animatedItemView:didTickCountdown:)
    optional func animatedItemView(_ itemView: CYLAnimatedItemView, didTickCountdown remainingSeconds: Int)
    /** [EN] The time is up. [CN] 时间到。 */
    @objc optional func animatedItemViewDidFinishCountdown(_ itemView: CYLAnimatedItemView)
    /** [EN] Whether a drag may start (asked only when `isDragEnabled`). [CN] 是否允许开始拖拽（仅在 `isDragEnabled` 时询问）。 */
    @objc optional func animatedItemViewShouldBeginDrag(_ itemView: CYLAnimatedItemView) -> Bool
    /** [EN] A drag started. [CN] 拖拽开始。 */
    @objc optional func animatedItemViewDidBeginDrag(_ itemView: CYLAnimatedItemView)
    /** [EN] The finger moved by `translation` points from where the drag started. [CN] 手指相对拖拽起点移动了 `translation` 点。 */
    @objc(animatedItemView:didDragWithTranslation:)
    optional func animatedItemView(_ itemView: CYLAnimatedItemView, didDragWithTranslation translation: CGPoint)
    /** [EN] The drag ended (or was cancelled) at `translation`. [CN] 拖拽在 `translation` 处结束（或取消）。 */
    @objc(animatedItemView:didEndDragWithTranslation:cancelled:)
    optional func animatedItemView(_ itemView: CYLAnimatedItemView, didEndDragWithTranslation translation: CGPoint, cancelled: Bool)
}

/// [EN] How often a running countdown reads the clock. The title changes only when the whole seconds left change, so a tick
///      that is a little late (a busy main thread) shows the right number, and the display is never ahead by more than this.
/// [CN] 运行中的倒计时读取时钟的间隔。只有剩余整秒数变化时才改变标题，因此 tick 稍有延迟（主线程繁忙）时仍显示正确的数字，显示最多超前此间隔。
private let cylAnimatedItemCountdownTickInterval: TimeInterval = 0.25

private let cylAnimatedItemCountdownNumberFormatter: NumberFormatter = {
    let formatter = NumberFormatter()
    formatter.locale = Locale.autoupdatingCurrent
    formatter.usesGroupingSeparator = false
    return formatter
}()

/// [EN] `format` with its `%ld` (or `%d`) replaced by `seconds`, in the user's digits. A replacement instead of
///      `String(format:)` because the format is the app's text, not a literal.
/// [CN] 把 `format` 中的 `%ld`（或 `%d`）替换为 `seconds`（使用用户所在地区的数字）。使用替换而不是 `String(format:)`，因为格式是 App 的文本，不是字面量。
private func cylAnimatedItemCountdownText(_ format: String, seconds: Int) -> String {
    let number = cylAnimatedItemCountdownNumberFormatter.string(from: NSNumber(value: seconds)) ?? String(seconds)
    return format.replacingOccurrences(of: "%ld", with: number).replacingOccurrences(of: "%d", with: number)
}

/// [EN] The default animation size, as the tab bar's. [CN] 默认动画尺寸，与 TabBar 一致。
private let cylAnimatedItemDefaultAnimationSide: CGFloat = 24

#if CYL_ANIMATION_ENGINE_AVAILABLE
/// [EN] How often a looping animation whose player has no `loops` checks whether it reached the end.
/// [CN] 播放器没有 `loops` 时，循环动画检查是否播放到末尾的间隔。
private let cylAnimatedItemLoopCheckInterval: TimeInterval = 0.05

/// [EN] Whether `url` is a local file that is missing, not a regular file, or empty: no animation view is made for it, so
///      the static image or the placeholder shows at once. Remote files are checked by the animator, which reports a failed
///      download or a corrupted file (`CYLTabBarItemAnimationReportFailure`).
/// [CN] `url` 是否为不存在、不是普通文件或为空的本地文件：不为其创建动画视图，立即显示静态图片或占位图。远程文件由 animator 检查，下载失败或文件损坏时报告
///      （`CYLTabBarItemAnimationReportFailure`）。
private func cylAnimatedItemLocalFileIsMissing(_ url: URL) -> Bool {
    guard url.isFileURL else { return false }
    let path = url.path
    if path.isEmpty { return true }
    guard let attributes = try? FileManager.default.attributesOfItem(atPath: path) else { return true }
    let size = (attributes[.size] as? NSNumber)?.uint64Value ?? 0
    return (attributes[.type] as? FileAttributeType) != .typeRegular || size == 0
}
#endif

/**
 [EN] An animated icon + title control to subclass, shared by the tags of CollectionViewClassifyMenu and
      CYLSearchViewController, the placeholders of CYLTableViewPlaceHolder and the tab buttons of CYLTabBarController:
      - an icon (`imageView`) that plays any file of the animation engine (`animationURL`), its static `image` /
        `selectedImage` shown until the animation is ready;
      - a title (`titleLabel`), beside the icon or under it (`axis`);
      - an optional accessory icon (`accessoryView`, e.g. a delete cross) with its own tap, placed before, after or on
        the icon's top trailing corner;
      - gestures on the whole control, reported to `delegate`: tap, long press and drag (`isDragEnabled`).
      Subclasses change what they need: the content (`CYLAnimatedItemContent`), the layout (`layoutContent(in:)`,
      `contentSizeThatFits(_:)`), the appearance per state (`itemStateDidChange()`), the accessibility text
      (`itemAccessibilityLabel()`), more gestures (add recognizers), or the animation source (`animationSource`). It is
      the CYLAnimatedItem pod and module (`import CYLAnimatedItem`; SwiftPM: `import CYLAnimatedItemViews`), which depends
      on no other pod, not on CYLTabBarController, and plays animations only when the engine is in the build (the Swift
      condition `CYL_ANIMATION_ENGINE_AVAILABLE`, set by the `Engine` subspec); static images otherwise. Written in Swift
      (2026-11-19, docs/Swift-Migration.md step 60) with the same Objective-C API: `@import CYLAnimatedItem;`.
 [CN] 可继承的动效 icon + title 控件，供 CollectionViewClassifyMenu 与 CYLSearchViewController 的标签、CYLTableViewPlaceHolder 的占位图以及
      CYLTabBarController 的 Tab 按钮共用：
      - 图标（`imageView`）可播放动画引擎支持的任意文件（`animationURL`），动画就绪前显示静态 `image` / `selectedImage`；
      - 标题（`titleLabel`），在图标旁或下方（`axis`）；
      - 可选的附加图标（`accessoryView`，例如删除叉号），有自己的点击，位于内容前、后或图标右上角；
      - 整个控件的手势，报告给 `delegate`：点击、长按与拖拽（`isDragEnabled`）。
      子类按需修改：内容（`CYLAnimatedItemContent`）、布局（`layoutContent(in:)`、`contentSizeThatFits(_:)`）、各状态的外观
      （`itemStateDidChange()`）、无障碍文本（`itemAccessibilityLabel()`）、更多手势（添加手势识别器）或动画来源（`animationSource`）。
      属于 CYLAnimatedItem pod 与模块（`import CYLAnimatedItem`；SwiftPM：`import CYLAnimatedItemViews`），不依赖任何其他 pod，也不依赖
      CYLTabBarController；只有引擎参与编译时才播放动画（Swift 条件 `CYL_ANIMATION_ENGINE_AVAILABLE`，由 `Engine` 子库设置），否则只显示静态图片。
      用 Swift 编写（2026-11-19，docs/Swift-Migration.md 第 60 步），Objective-C API 不变：`@import CYLAnimatedItem;`。
 */
@objc(CYLAnimatedItemView)
@objcMembers
open class CYLAnimatedItemView: UIControl, CYLAnimatedItemContent, CYLAnimatedItemAnimating, UIGestureRecognizerDelegate {

    // MARK: - Subviews 子视图

    /** [EN] The static icon. Hidden from accessibility (the control reads as one element). [CN] 静态图标。对无障碍隐藏（控件作为一个元素朗读）。 */
    public let imageView = UIImageView()
    /**
     [EN] The title label, with Dynamic Type. Hidden from accessibility (its text is part of the control's).
     [CN] 标题标签，支持动态字体。对无障碍隐藏（文字包含在控件的文本中）。
     */
    public let titleLabel = UILabel()

    /**
     [EN] The library's placeholder: `cyl_animated_item_placeholder` in `CYLAnimatedItem.bundle`, a 25 x 25 pt template image
          sized for a tab icon (it takes the tint). nil when the bundle is not in the app.
     [CN] 本库的占位图：`CYLAnimatedItem.bundle` 中的 `cyl_animated_item_placeholder`，25 x 25 pt、适合 Tab 图标的模板图（跟随 tint 颜色）。
          App 中没有该资源包时为 nil。
     */
    public class var defaultPlaceholderImage: UIImage? { CYLAnimatedItemView.sharedPlaceholderImage }

    private static let sharedPlaceholderImage: UIImage? = {
        guard let bundle = cylAnimatedItemResourceBundleEntryPoint() else { return nil }
        return UIImage(named: "cyl_animated_item_placeholder", in: bundle, compatibleWith: nil)?.withRenderingMode(.alwaysTemplate)
    }()

    /**
     [EN] Shown when there is no static image (`image` / `selectedImage`) and `animationURL` cannot play: no animation engine,
          no library for the file, or a file it cannot read. Set nil to go back to `defaultPlaceholderImage`, or an empty
          `UIImage` to show none (the title alone). The animation still wins once it can play.
     [CN] 没有静态图片（`image` / `selectedImage`）且 `animationURL` 无法播放（没有动画引擎、没有该文件的动画库或文件无法读取）时显示。设为 nil
          恢复为 `defaultPlaceholderImage`，设为空的 `UIImage` 则不显示（只有标题）。动画能播放时仍优先显示动画。
     */
    open var placeholderImage: UIImage! {
        get { storedPlaceholderImage ?? type(of: self).defaultPlaceholderImage }
        set {
            storedPlaceholderImage = newValue
            updateIcon()
            contentDidChange()
        }
    }
    private var storedPlaceholderImage: UIImage?

    /**
     [EN] The view playing `animationURL`, while ready; always nil without the animation engine.
     [CN] 正在播放 `animationURL` 的视图（就绪时）；没有动画引擎时始终为 nil。
     */
    open var animationView: UIView? { storedAnimationView }
    private var storedAnimationView: UIView?

    #if CYL_ANIMATION_ENGINE_AVAILABLE
    /**
     [EN] The player of `animationView`. Only with the animation engine (`CYL_ANIMATION_ENGINE_AVAILABLE`).
     [CN] `animationView` 的播放器。仅在有动画引擎时提供（`CYL_ANIMATION_ENGINE_AVAILABLE`）。
     */
    public var animationPlayer: CYLTabBarItemAnimationPlayer? {
        guard let view = animationView else { return nil }
        return animationSource.player(for: view)
    }

    /**
     [EN] Where animation views come from: `+[CYLTabBarItemAnimationFactory sharedFactory]` by default. A library with its
          own registry (or a test) sets another factory. Only with the animation engine.
     [CN] 动画视图的来源：默认为 `+[CYLTabBarItemAnimationFactory sharedFactory]`。有自己注册表的库（或测试）可以设置其他工厂。仅在有动画引擎时提供。
     */
    public var animationSource: CYLTabBarItemAnimationViewMaking! {
        get { storedAnimationSource ?? CYLTabBarItemAnimationFactory.shared() }
        set {
            storedAnimationSource = newValue
            reloadAnimation()
        }
    }
    private var storedAnimationSource: CYLTabBarItemAnimationViewMaking?
    #endif

    /** [EN] The delegate of taps, long presses, accessory taps and drags. [CN] 点击、长按、附加图标点击与拖拽的代理。 */
    public weak var delegate: CYLAnimatedItemViewDelegate?

    // MARK: - Content 内容

    /** [EN] The title, or nil for an icon-only item. [CN] 标题；只有图标时为 nil。 */
    @objc open dynamic var title: String? {
        didSet {
            titleLabel.text = title
            updateItemAccessibility()
            contentDidChange()
        }
    }
    /** [EN] The static icon. [CN] 静态图标。 */
    @objc open dynamic var image: UIImage? {
        didSet {
            updateIcon()
            contentDidChange()
        }
    }
    /** [EN] The icon while selected; nil uses `image`. [CN] 选中时的图标；为 nil 时使用 `image`。 */
    @objc open dynamic var selectedImage: UIImage? {
        didSet { updateIcon() }
    }

    // MARK: - Layout properties 布局属性

    /** [EN] Icon beside the title (default) or above it. [CN] 图标在标题旁（默认）或上方。 */
    @objc public dynamic var axis: CYLAnimatedItemAxis = .horizontal { didSet { contentDidChange() } }
    /** [EN] Centered (default) or against the leading edge. [CN] 居中（默认）或靠前缘。 */
    public var alignment: CYLAnimatedItemAlignment = .center { didSet { setNeedsLayout() } }
    /** [EN] Space between the icon, the title and the accessory (4 by default). [CN] 图标、标题与附加图标之间的间距（默认 4）。 */
    @objc public dynamic var spacing: CGFloat = 4 { didSet { contentDidChange() } }
    /** [EN] Insets around the content. [CN] 内容四周的内边距。 */
    @objc public dynamic var contentInsets: UIEdgeInsets = .zero { didSet { contentDidChange() } }
    /**
     [EN] The icon's size; CGSizeZero (default) uses the image's own size, and 24 x 24 for an animation.
     [CN] 图标尺寸；CGSizeZero（默认）使用图片自身尺寸，动画为 24 x 24。
     */
    @objc public dynamic var iconSize: CGSize = .zero { didSet { reloadAnimation() } }

    /**
     [EN] An optional second icon with its own tap (`animatedItemViewDidTapAccessory(_:)`), e.g. a delete cross; nil removes
          it. It is its own accessibility element: give it an `accessibilityLabel`.
     [CN] 可选的第二个图标，有自己的点击（`animatedItemViewDidTapAccessory(_:)`），例如删除叉号；nil 移除。它是独立的无障碍元素：请设置
          `accessibilityLabel`。
     */
    @objc open dynamic var accessoryView: UIView? {
        get { storedAccessoryView }
        set {
            guard storedAccessoryView !== newValue else { return }
            storedAccessoryView?.removeFromSuperview()
            storedAccessoryView = newValue
            if let accessory = newValue {
                accessory.isUserInteractionEnabled = true
                accessory.isAccessibilityElement = true
                accessory.accessibilityTraits.insert(.button)
                if let control = accessory as? UIControl {
                    control.addTarget(self, action: #selector(handleAccessoryTap), for: .touchUpInside)
                } else {
                    accessory.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(handleAccessoryTap)))
                }
                addSubview(accessory)
            }
            contentDidChange()
        }
    }
    private var storedAccessoryView: UIView?
    /** [EN] Where the accessory goes (after the content by default). [CN] 附加图标的位置（默认在内容之后）。 */
    public var accessoryPlacement: CYLAnimatedItemAccessoryPlacement = .trailing { didSet { contentDidChange() } }
    /** [EN] The accessory's size (18 x 18 by default). [CN] 附加图标的尺寸（默认 18 x 18）。 */
    public var accessorySize = CGSize(width: 18, height: 18) { didSet { contentDidChange() } }

    // MARK: - Countdown properties 倒计时属性

    /**
     [EN] The look: plain (default) or a countdown button. Countdown gives the control a border and a rounded corner and
          manages its title; set the `countdown…` properties, then call `startCountdown()` (or set `startsCountdownOnTap`).
          The end is kept as a date, not counted by a timer: the seconds that pass while the app is in the background, or the
          device is locked, still count (the time left is read again on every tick and when the app returns), and a late timer
          cannot make it drift (FIX: issue #1 of SMSCodeButton). Only the title changes, once per second, on the same label:
          no system button is rebuilt, so nothing flickers; the control keeps the width of its widest title, so it does not
          jump either. While it runs the control is disabled, and VoiceOver reads the remaining seconds.
     [CN] 样式：普通（默认）或倒计时按钮。倒计时样式为控件加上边框与圆角并接管标题；设置 `countdown…` 属性后调用 `startCountdown()`
          （或设置 `startsCountdownOnTap`）。结束时间保存为日期，而不是靠定时器累减：App 在后台、设备锁屏期间经过的秒数同样计入
          （每次 tick 与 App 返回前台时重新读取剩余时间），定时器延迟也不会造成偏差（修复 SMSCodeButton 的 issue #1）。每秒只改变同一个
          label 的标题，不重建系统按钮，因此不会闪烁；控件保持最宽标题的宽度，也不会抖动。倒计时期间控件不可用，VoiceOver 朗读剩余秒数。
     */
    public var itemStyle: CYLAnimatedItemStyle = .plain {
        didSet { countdownStyleDidChange(from: oldValue) }
    }
    /** [EN] The length in seconds, 60 by default. Used by `startCountdown()`. [CN] 总时长（秒），默认 60。`startCountdown()` 使用。 */
    public var countdownDuration: TimeInterval = 60
    /**
     [EN] The title before it starts, e.g. "Get code" (the default text is English; set the app's localized text).
     [CN] 开始前的标题，例如「获取验证码」（默认文本为英文；请设置 App 本地化后的文本）。
     */
    public var countdownIdleTitle = "Get code" { didSet { refreshCountdownTitle() } }
    /**
     [EN] The title while counting: a format with one `%ld`, the whole seconds left, e.g. "%ld s left".
     [CN] 倒计时中的标题：带一个 `%ld`（剩余整秒数）的格式，例如「还剩%ld秒」。
     */
    public var countdownRunningTitleFormat = "%ld s left" { didSet { refreshCountdownTitle() } }
    /** [EN] The title once the time is up, e.g. "Resend". [CN] 时间到之后的标题，例如「重新获取」。 */
    public var countdownFinishedTitle = "Resend" { didSet { refreshCountdownTitle() } }
    /** [EN] The icon while counting (e.g. a clock); nil keeps `image`. [CN] 倒计时中的图标（例如时钟）；为 nil 时保持 `image`。 */
    public var countdownImage: UIImage? {
        didSet {
            updateIcon()
            contentDidChange()
        }
    }
    /**
     [EN] The title color while counting (gray by default). Idle and finished use `titleLabel.textColor`.
     [CN] 倒计时中的标题颜色（默认灰色）。待机与结束使用 `titleLabel.textColor`。
     */
    public var countdownRunningTitleColor: UIColor = .gray { didSet { applyCountdownAppearance() } }
    /**
     [EN] Whether a tap starts the countdown after the delegate's `animatedItemViewDidTap(_:)` (off by default). With it off
          the app starts it itself, e.g. once the server accepted the request.
     [CN] 点击是否在代理的 `animatedItemViewDidTap(_:)` 之后开始倒计时（默认关闭）。关闭时由 App 自己开始，例如服务器接受请求之后。
     */
    public var startsCountdownOnTap = false
    /** [EN] Where the countdown is. [CN] 倒计时所处的阶段。 */
    public private(set) var countdownState: CYLAnimatedItemCountdownState = .idle
    /** [EN] When the running countdown ends; nil when it is not running. [CN] 运行中的倒计时的结束时间；未运行时为 nil。 */
    public private(set) var countdownEndDate: Date?
    /** [EN] The clock, for tests: `Date()` by default (nil). [CN] 时钟，供测试使用：默认为 `Date()`（nil）。 */
    public var countdownDateProvider: (() -> Date)?
    /** [EN] The whole seconds left (rounded up): 0 when it is not running. [CN] 剩余整秒数（向上取整）：未运行时为 0。 */
    public var countdownRemainingSeconds: Int {
        guard countdownState == .running, let end = countdownEndDate else { return 0 }
        let left = end.timeIntervalSince(cylNow)
        return left > 0 ? Int(ceil(left)) : 0
    }
    /**
     [EN] A key that keeps the running countdown in `countdownCacheStore`, so it survives the app being ended in the background
          (or quit) and started again: a view with the same key, in the countdown style, takes it up again, with the seconds
          that passed meanwhile counted. The cache holds the start, the end and the longest duration; it is dropped when the
          time is up, on `resetCountdown()`, and when it is no longer valid (see `refreshCountdown()`). nil (default): nothing
          is kept. Use one key per thing counted, e.g. one per phone number.
     [CN] 用于把运行中的倒计时保存到 `countdownCacheStore` 的 key，使倒计时在 App 于后台被结束（或退出）后再次启动时仍然有效：
          样式为倒计时且 key 相同的视图会接着倒计时，期间经过的秒数同样计入。缓存保存开始时间、结束时间与最长时长；时间到、
          `resetCountdown()` 以及缓存失效（见 `refreshCountdown()`）时丢弃。nil（默认）：不保存。每个被计时的对象使用一个 key，例如每个手机号一个。
     */
    public var countdownCacheKey: String? {
        didSet {
            guard countdownCacheKey != oldValue else { return }
            if let old = oldValue { countdownCacheStore.removeObject(forKey: Self.countdownCacheName(old)) }
            if countdownState == .running {
                saveCountdownToCache()
            } else {
                restoreCountdownFromCache()
            }
        }
    }
    /** [EN] Where the cache is kept: `UserDefaults.standard` by default; an app group's suite, or one for tests. [CN] 缓存的保存位置：默认为 `UserDefaults.standard`；也可以是 App Group 的 suite，或测试用的 suite。 */
    public var countdownCacheStore: UserDefaults = .standard
    private var countdownTimer: Timer?
    private var countdownStartDate: Date?
    private var countdownShownSeconds = -1
    private var countdownRunDuration: TimeInterval = 0
    private var countdownRestingTitleColor: UIColor?

    // MARK: - Gestures 手势

    /** [EN] Whether the control reports drags (off by default). [CN] 是否报告拖拽（默认关闭）。 */
    @objc(dragEnabled) public var isDragEnabled: Bool {
        @objc(isDragEnabled) get { storedDragEnabled }
        set {
            storedDragEnabled = newValue
            panGestureRecognizer.isEnabled = newValue
        }
    }
    private var storedDragEnabled = false
    /** [EN] Whether a drag moves the control (transform) and springs it back at the end. [CN] 拖拽时控件是否跟随移动（transform），结束后弹回。 */
    public var dragMovesView = false
    /**
     [EN] The recognizers the control uses, for subclasses that combine their own gestures with them.
     [CN] 控件使用的手势识别器，供子类与自己的手势组合使用。
     */
    public private(set) var longPressGestureRecognizer: UILongPressGestureRecognizer!
    /** [EN] The drag recognizer, enabled with `isDragEnabled`. [CN] 拖拽手势识别器，随 `isDragEnabled` 启用。 */
    public private(set) var panGestureRecognizer: UIPanGestureRecognizer!

    // MARK: - Icon visibility 图标可见性

    /**
     [EN] Keeps the icon hidden (the image view, and the animation view while it is set), e.g. while another view is shown in
          its place: the tab bar sets it for a view shown instead of a tab's icon (#601,
          `-cyl_replaceTabImageViewWithNewView:…`). The item's own icon updates (selection, a new image, an animation that
          loads) respect it. false by default.
     [CN] 让图标保持隐藏（图片视图，以及设置期间的动画视图），例如另一个视图显示在其位置时：TabBar 在用其他视图替换 Tab 图标时设置（#601、
          `-cyl_replaceTabImageViewWithNewView:…`）。item 自身的图标更新（选中、新图片、动画加载）都会遵守它。默认为 false。
     */
    @objc(iconHidden) public var isIconHidden: Bool {
        @objc(isIconHidden) get { storedIconHidden }
        set {
            guard storedIconHidden != newValue else { return }
            storedIconHidden = newValue
            updateIcon()
        }
    }
    private var storedIconHidden = false

    // MARK: - Item appearance 外观

    /**
     [EN] The icon and title part of a tab bar item's appearance, as `UITabBarAppearance.stackedLayoutAppearance`: for the
          current state (disabled, else selected, else normal), `iconColor` tints the icon (`imageView`, template images)
          and the animation view (when it takes a tint, e.g. a Rive file with the `tint` option), `titleTextAttributes`
          styles `titleLabel` (font and color), `titlePositionAdjustment` moves the title. Values a state does not set leave
          the item's own look. Badge values are not used. nil (the default): the item's own look. The FlatDesign tab bar
          assigns its `standardAppearance` here.
     [CN] Tab bar item 外观中图标与标题的部分，与 `UITabBarAppearance.stackedLayoutAppearance` 相同：按当前状态（不可用，否则选中，否则普通），
          `iconColor` 为图标（`imageView`，模板图片）与动画视图（接受着色时，例如带 `tint` 选项的 Rive 文件）着色，`titleTextAttributes` 设置
          `titleLabel` 的样式（字体与颜色），`titlePositionAdjustment` 移动标题。某状态未设置的值保持 item 自身的外观。不使用角标的值。nil（默认）：
          item 自身的外观。扁平样式 TabBar 会把其 `standardAppearance` 赋值到这里。
     */
    @NSCopying public var itemAppearance: UITabBarItemAppearance? {
        didSet {
            if oldValue === itemAppearance { return }
            applyItemAppearance()
            contentDidChange()
        }
    }

    /**
     [EN] The state appearance of `itemAppearance` for the current state (disabled, else selected, else normal); nil without one.
     [CN] `itemAppearance` 中当前状态（不可用，否则选中，否则普通）的 state appearance；没有 `itemAppearance` 时为 nil。
     */
    public var currentItemStateAppearance: UITabBarItemStateAppearance? {
        guard let appearance = itemAppearance else { return nil }
        if !isEnabled { return appearance.disabled }
        return isSelected ? appearance.selected : appearance.normal
    }

    // MARK: - Animation state 动画状态

    /** [EN] The animation file; nil removes the animation. [CN] 动画文件；nil 移除动画。 */
    @objc open dynamic var animationURL: URL? {
        didSet {
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            guard animationURL != oldValue else { return }
            reloadAnimation()
            #else
            // [EN] No engine: the file cannot play, so the placeholder shows when there is no static image.
            // [CN] 没有引擎：文件无法播放，没有静态图片时显示占位图。
            updateIcon()
            contentDidChange()
            #endif
        }
    }
    /** [EN] Speed, 1 by default. [CN] 速度，默认 1。 */
    open var animationSpeed: CGFloat = 1 {
        didSet {
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            applyPlayerSettings()
            #endif
        }
    }
    /** [EN] Whether the animation loops. [CN] 动画是否循环播放。 */
    open var animationLoops = false {
        didSet {
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            applyPlayerSettings()
            if !animationLoops {
                stopLoopTimer()
            } else if playing {
                startLoopTimerIfNeeded()
            }
            #endif
        }
    }
    /**
     [EN] Grows by one on every `restartAnimation()` (Play all), the name and meaning of HarmonyOS's `animationRestartToken`:
          a host that sees it change knows the item restarted. Read only here; React Native and Flutter call
          `restartAnimation()` when their own restart token prop changes.
     [CN] 每次 `restartAnimation()`（全部播放）加一，名称与含义同鸿蒙的 `animationRestartToken`：宿主看到它变化就知道条目重新播放了。这里只读；
          React Native 与 Flutter 在各自的重播 token 属性变化时调用 `restartAnimation()`。
     */
    public private(set) var animationRestartToken = 0
    /**
     [EN] Whether the view applies its default playback rules to the animation's player: `animationSpeed`, `animationLoops`
          (also the loop restart for a player without a loop mode) and `animationRestingProgress`. true by default; false
          (HarmonyOS's `drivesAnimationPlayback: false`): the view only hands out `animationPlayer` and the host drives it.
          `playAnimation()`, `restartAnimation()` and `stopAnimation()` still call the player when the host asks. The end
          callback `onAnimationEnd` is not a rule and is kept.
     [CN] 视图是否对动画的播放器应用默认播放规则：`animationSpeed`、`animationLoops`（含没有循环模式的播放器的循环重播）与
          `animationRestingProgress`。默认为 true；false（鸿蒙的 `drivesAnimationPlayback: false`）：视图只提供 `animationPlayer`，由宿主驱动。
          宿主调用 `playAnimation()`、`restartAnimation()`、`stopAnimation()` 时仍会操作播放器。结束回调 `onAnimationEnd` 不属于规则，保持有效。
     */
    public var drivesAnimationPlayback = true {
        didSet {
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            guard drivesAnimationPlayback != oldValue else { return }
            if drivesAnimationPlayback {
                applyPlayerSettings()
                if !playing { setPlayerValue(storedRestingProgress, for: "progress") }
                if animationLoops, playing { startLoopTimerIfNeeded() }
            } else {
                stopLoopTimer()
            }
            #endif
        }
    }
    /**
     [EN] Called on the main queue when a play-once pass (`animationLoops` off) reaches its end: not on a stop, not while
          looping, and only for an engine that can tell (`CYLTabBarItemAnimationPlayer.onEnded`). Replaces the player's own
          `onEnded` as long as the view owns the callback; a host that sets `animationPlayer`'s `onEnded` takes it over.
     [CN] 只播放一次（`animationLoops` 关闭）的一遍播放到结尾时在主队列调用：停止时不调用，循环时不调用，且只有能判断结束的引擎才会调用
          （`CYLTabBarItemAnimationPlayer.onEnded`）。视图拥有该回调期间会占用播放器自己的 `onEnded`；宿主设置 `animationPlayer` 的 `onEnded` 即接管。
     */
    public var onAnimationEnd: (() -> Void)?
    /**
     [EN] Whether a play-once animation (`animationLoops` off) is replaced by the still image when it ends, the name and meaning of
          HarmonyOS's and Android's `showsImageWhenAnimationEnds`: the animation view is hidden and `imageView` shows
          `selectedImage` / `image` (else the placeholder). false by default, so the last frame stays. The next
          `playAnimation()`, `restartAnimation()`, `stopAnimation()` or `showAnimationLastFrame()` shows the animation again.
          For an animation whose last frame is empty (a success check that fades out). Needs an engine that can tell the end
          (`CYLTabBarItemAnimationPlayer.onEnded`); `onAnimationEnd` is called after the image is shown.
     [CN] 只播放一次（`animationLoops` 关闭）的动画结束时是否换成静态图片，名称与含义同鸿蒙与 Android 的 `showsImageWhenAnimationEnds`：
          隐藏动画视图，`imageView` 显示 `selectedImage` / `image`（没有时显示占位图）。默认为 false，保留最后一帧。下一次 `playAnimation()`、
          `restartAnimation()`、`stopAnimation()` 或 `showAnimationLastFrame()` 会重新显示动画。用于最后一帧为空的动画（逐渐消失的成功对勾）。
          需要能判断结束的引擎（`CYLTabBarItemAnimationPlayer.onEnded`）；显示图片之后才调用 `onAnimationEnd`。
     */
    public var showsImageWhenAnimationEnds = false {
        didSet { if !showsImageWhenAnimationEnds { showAnimationAgain() } }
    }
    /** [EN] Whether the still image replaces the ended animation now (`showsImageWhenAnimationEnds`). [CN] 静态图片当前是否替换了已结束的动画。 */
    public private(set) var isShowingImageAfterAnimationEnd = false
    /**
     [EN] Called on the main queue when the animation of `animationURL` is in place (a local file once parsed, a download once
          it arrived), the name and meaning of HarmonyOS's `onAnimationLoaded`. React Native and Flutter forward it as `onAnimationLoaded`.
     [CN] `animationURL` 的动画就绪时在主队列调用（本地文件解析完成，或下载完成），名称与含义同鸿蒙的 `onAnimationLoaded`。
          React Native 与 Flutter 把它转发为 `onAnimationLoaded`。
     */
    public var onAnimationLoaded: (() -> Void)?
    /**
     [EN] Called on the main queue when the animation of `animationURL` cannot play: a missing file, a corrupted file, a parse error
          or a failed download (the static image or the placeholder shows instead), HarmonyOS's `onAnimationFailed`.
     [CN] `animationURL` 的动画无法播放时在主队列调用：文件不存在、文件损坏、解析错误或下载失败（此时显示静态图片或占位图），
          同鸿蒙的 `onAnimationFailed`。
     */
    public var onAnimationFailed: (() -> Void)?
    /** [EN] The progress shown while not playing, clamped to 0...1. [CN] 未播放时显示的进度，限制在 0...1。 */
    open var animationRestingProgress: CGFloat {
        get { storedRestingProgress }
        set {
            storedRestingProgress = min(1, max(0, newValue))
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            if !playing, drivesAnimationPlayback { setPlayerValue(storedRestingProgress, for: "progress") }
            #endif
        }
    }
    private var storedRestingProgress: CGFloat = 0

    /** [EN] Whether the animation view is in place. [CN] 动画视图是否已就绪。 */
    @objc(animationReady) open var isAnimationReady: Bool {
        @objc(isAnimationReady) get {
            #if CYL_ANIMATION_ENGINE_AVAILABLE
            return animationView != nil
            #else
            return false
            #endif
        }
    }

    private var loopTimer: Timer?
    /// [EN] The animated image shown on its first frame until it is played. [CN] 播放前停在第一帧显示的动图。
    private var restingAnimatedImage: UIImage?

    /**
     [EN] Plays the frames of an animated `image` / `selectedImage` from the first one (once, or looping with
          `animationLoops`); false when the icon is not an animated image. `playAnimation()` and `restartAnimation()` call it
          when there is no animation file; a subclass whose own animation is elsewhere (the FlatDesign tab button) calls it too.
     [CN] 从第一帧播放动图 `image` / `selectedImage` 的各帧（播放一次，`animationLoops` 时循环）；图标不是动图时返回 false。没有动画文件时由
          `playAnimation()` 与 `restartAnimation()` 调用；动画在别处的子类（扁平样式 Tab 按钮）也可以调用。
     */
    @objc(playAnimatedImage)
    @discardableResult
    open func playAnimatedImage() -> Bool {
        playAnimatedImage(restingAnimatedImage)
    }

    /**
     [EN] Plays the frames of `animatedImage` on the icon (once, or looping with `animationLoops`), then shows the resting icon
          again; false when it is not an animated image. For a subclass whose animated source is not its current `image`.
     [CN] 在图标上播放 `animatedImage` 的各帧（播放一次，`animationLoops` 时循环），之后恢复显示静止图标；不是动图时返回 false。供动图来源不是当前
          `image` 的子类使用。
     */
    @objc(playAnimatedImage:)
    @discardableResult
    open func playAnimatedImage(_ animatedImage: UIImage?) -> Bool {
        guard let animated = animatedImage, let frames = animated.images, frames.count > 1 else { return false }
        imageView.stopAnimating()
        imageView.animationImages = frames.map { $0.withRenderingMode(animated.renderingMode) }
        imageView.animationDuration = animated.duration
        imageView.animationRepeatCount = animationLoops ? 0 : 1
        imageView.startAnimating()
        postAnimationEvent("cyl.animation.didStart")
        return true
    }

    /**
     [EN] Stops the frames of an animated image and shows its first frame again. [CN] 停止动图的帧动画，重新显示其第一帧。
     */
    @objc(stopAnimatedImage)
    open func stopAnimatedImage() {
        guard imageView.isAnimating || imageView.animationImages != nil else { return }
        let wasAnimating = imageView.isAnimating || pausedAnimatedImage
        imageView.stopAnimating()
        imageView.animationImages = nil
        pausedAnimatedImage = false
        pausedByScroll = false
        updateIcon()
        if wasAnimating { postAnimationEvent("cyl.animation.didStop") }
    }
    private var playing = false
    private var pausedByScroll = false
    private var pausedAnimatedImage = false
    private var speedBeforePause: CGFloat = 1
    /// [EN] The icon tint applied last (`applyIconTintColor(_:)`), given again to a new animation view. [CN] 最近应用的图标着色，再次交给新的动画视图。
    private var lastIconTintColor: UIColor?

    // MARK: - Life cycle 生命周期

    public override init(frame: CGRect) {
        super.init(frame: frame)
        animatedItemSetUp()
    }

    public required init?(coder: NSCoder) {
        super.init(coder: coder)
        animatedItemSetUp()
    }

    deinit {
        loopTimer?.invalidate()
        countdownTimer?.invalidate()
        NotificationCenter.default.removeObserver(self)
    }

    /**
     [EN] Asks CYLTabBarController's event bridge (when that module is linked) to install itself, once, so an item used on its
          own (a stack view, a table placeholder, React Native, Flutter) also posts `cyl.animation.*` as lifecycle events and can
          be paused. Found by name: this pod never depends on CYLTabBarController; without it nothing happens.
     [CN] 请求 CYLTabBarController 的事件桥接（已链接该模块时）安装自己，只执行一次，使单独使用的控件（stack view、表格占位、
          React Native、Flutter）同样把 `cyl.animation.*` 作为生命周期事件发出并可被暂停。按名称查找：本 pod 从不依赖
          CYLTabBarController；没有它时什么都不发生。
     */
    private static let installEventBridge: Void = {
        _ = (NSClassFromString("CYLAnimationEventBridgeInstaller") as AnyObject?)?.perform(NSSelectorFromString("install"))
    }()

    private func animatedItemSetUp() {
        _ = Self.installEventBridge
        imageView.contentMode = .scaleAspectFit
        imageView.isAccessibilityElement = false
        imageView.accessibilityElementsHidden = true
        addSubview(imageView)

        titleLabel.font = UIFont.preferredFont(forTextStyle: .subheadline)
        titleLabel.adjustsFontForContentSizeCategory = true
        titleLabel.textAlignment = .center
        titleLabel.lineBreakMode = .byTruncatingTail
        titleLabel.isAccessibilityElement = false
        addSubview(titleLabel)

        let longPress = UILongPressGestureRecognizer(target: self, action: #selector(handleLongPress(_:)))
        longPress.delegate = self
        addGestureRecognizer(longPress)
        longPressGestureRecognizer = longPress

        let pan = UIPanGestureRecognizer(target: self, action: #selector(handlePan(_:)))
        pan.delegate = self
        pan.isEnabled = false
        addGestureRecognizer(pan)
        panGestureRecognizer = pan

        addTarget(self, action: #selector(handleTap), for: .touchUpInside)

        isAccessibilityElement = true
        accessibilityTraits = .button
        accessibilityIdentifier = "CYLAnimatedItemView"
    }

    // MARK: - Icon 图标

    /// [EN] The placeholder, when there is no static image and the animation file cannot play. [CN] 没有静态图片且动画文件无法播放时的占位图。
    private func placeholderIfNeeded() -> UIImage? {
        if image != nil || selectedImage != nil || animationURL == nil || animationShows() { return nil }
        guard let placeholder = placeholderImage, placeholder.size.width > 0, placeholder.size.height > 0 else { return nil }
        return placeholder
    }

    /// [EN] Whether the animation is on screen: made, and not waiting for its file (a download). Until then the static image
    ///      given, or the placeholder when there is none, shows.
    /// [CN] 动画是否已显示：已创建且不在等待其文件（下载）。在此之前显示传入的静态图片，没有时显示占位图。
    private func animationShows() -> Bool {
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        guard let view = animationView, !isShowingImageAfterAnimationEnd else { return false }
        return !CYLTabBarItemAnimationIsLoading(view)
        #else
        return false
        #endif
    }

    private func updateIcon() {
        var icon = (isSelected && selectedImage != nil) ? selectedImage : image
        if countdownState == .running, let countdownIcon = countdownImage { icon = countdownIcon }
        if icon == nil { icon = placeholderIfNeeded() }
        // [EN] An animated image (`UIImage.images`, e.g. a GIF) rests on its first frame until it is played, like an animation
        //      file (docs/Animated-Item.md, "every animated tab icon rests until it is played"); `playAnimation()` plays it.
        // [CN] 动图（`UIImage.images`，例如 GIF）与动画文件一样，在播放前停在第一帧（docs/Animated-Item.md，「每个动效 Tab 图标在播放前保持静止」）；
        //      `playAnimation()` 播放它。
        // [EN] A static selected icon over an animated `image` plays the `image`'s frames, as the classic tab bar does.
        // [CN] 静态的选中图标搭配动图 `image` 时播放 `image` 的帧，与经典 TabBar 相同。
        let iconIsAnimated = (icon?.images?.count ?? 0) > 1
        let imageIsAnimated = (image?.images?.count ?? 0) > 1
        let source: UIImage?
        if iconIsAnimated {
            source = icon
        } else if imageIsAnimated {
            source = image
        } else {
            source = nil
        }
        if let animated = source, let shown = icon {
            restingAnimatedImage = animated
            if !imageView.isAnimating {
                imageView.image = iconIsAnimated ? shown.images![0].withRenderingMode(shown.renderingMode) : shown
            }
        } else {
            restingAnimatedImage = nil
            imageView.stopAnimating()
            imageView.animationImages = nil
            imageView.image = icon
        }
        // [EN] `isIconHidden`: another view is shown in the icon's place. [CN] `isIconHidden`：另一个视图显示在图标的位置。
        imageView.isHidden = isIconHidden || animationShows()
        animationView?.isHidden = isIconHidden || isShowingImageAfterAnimationEnd
        // [EN] A new animation view or icon takes the current icon tint. [CN] 新的动画视图或图标使用当前的图标着色。
        if let color = currentItemStateAppearance?.iconColor ?? lastIconTintColor {
            applyIconTintColor(color)
        }
    }

    private func contentDidChange() {
        invalidateIntrinsicContentSize()
        setNeedsLayout()
    }

    // MARK: - Measuring and layout 测量与布局

    private var cylShowsIcon: Bool { animationView != nil || imageView.image != nil }
    private var cylShowsTitle: Bool { !(title ?? "").isEmpty }
    private var accessoryInline: Bool { accessoryView != nil && accessoryPlacement != .topTrailing }

    private var currentIconSize: CGSize {
        guard cylShowsIcon else { return .zero }
        if iconSize.width > 0 && iconSize.height > 0 { return iconSize }
        if animationView != nil { return CGSize(width: cylAnimatedItemDefaultAnimationSide, height: cylAnimatedItemDefaultAnimationSide) }
        return imageView.image?.size ?? .zero
    }

    /**
     [EN] Subclass hook: the content's natural size (without `contentInsets`) for a width limit. Override together with
          `layoutContent(in:)` for another arrangement.
     [CN] 子类钩子：给定宽度上限时内容的自然尺寸（不含 `contentInsets`）。需要其他排列时与 `layoutContent(in:)` 一起重写。
     */
    open func contentSizeThatFits(_ size: CGSize) -> CGSize {
        let icon = currentIconSize
        let showsIcon = cylShowsIcon
        let showsTitle = cylShowsTitle
        let gap = (showsIcon && showsTitle) ? spacing : 0
        let accessory = accessoryInline ? accessorySize.width : 0
        let accessorySpacing = (accessory > 0 && (showsIcon || showsTitle)) ? spacing : 0
        let titleLimit = max(0, size.width - accessory - accessorySpacing - (axis == .horizontal ? icon.width + gap : 0))
        var titleSize = showsTitle ? titleLabel.sizeThatFits(CGSize(width: titleLimit, height: .greatestFiniteMagnitude)) : .zero
        titleSize.width = min(ceil(titleSize.width), titleLimit)
        if showsTitle { titleSize.width = min(max(titleSize.width, countdownTitleWidth), titleLimit) }
        titleSize.height = ceil(titleSize.height)
        let accessoryHeight = accessoryInline ? accessorySize.height : 0
        if axis == .horizontal {
            return CGSize(width: icon.width + gap + titleSize.width + accessory + accessorySpacing,
                          height: max(max(icon.height, titleSize.height), accessoryHeight))
        }
        return CGSize(width: max(icon.width, titleSize.width) + accessory + accessorySpacing,
                      height: max(icon.height + gap + titleSize.height, accessoryHeight))
    }

    open override func sizeThatFits(_ size: CGSize) -> CGSize {
        let insets = contentInsets
        let limit = (size.width > 0 ? size.width : .greatestFiniteMagnitude) - insets.left - insets.right
        let content = contentSizeThatFits(CGSize(width: max(0, limit), height: size.height))
        return CGSize(width: ceil(content.width + insets.left + insets.right), height: ceil(content.height + insets.top + insets.bottom))
    }

    open override var intrinsicContentSize: CGSize {
        sizeThatFits(CGSize(width: CGFloat.greatestFiniteMagnitude, height: .greatestFiniteMagnitude))
    }

    open override func layoutSubviews() {
        super.layoutSubviews()
        layoutContent(in: bounds.inset(by: contentInsets))
        applyCountdownAppearance()
    }

    /**
     [EN] The x of a stacked (icon above title) element of `width`: leading aligned, at the leading edge (the trailing one in
          right-to-left); otherwise centered.
     [CN] 堆叠布局（图标在标题上方）中宽度为 `width` 的元素的 x：靠前对齐时位于前缘（从右到左时为后缘）；否则居中。
     */
    private static func cylStackedX(width: CGFloat, in content: CGRect, leadingAligned: Bool, rtl: Bool) -> CGFloat {
        guard leadingAligned else {
            return content.midX - width / 2
        }
        return rtl ? content.maxX - width : content.minX
    }

    /**
     [EN] Subclass hook: places the icon, the animation view, the title and the accessory in `rect` (the bounds minus
          `contentInsets`).
     [CN] 子类钩子：在 `rect`（边界减去 `contentInsets`）中放置图标、动画视图、标题与附加图标。
     */
    @objc(layoutContentInRect:)
    open func layoutContent(in rect: CGRect) {
        let rtl = effectiveUserInterfaceLayoutDirection == .rightToLeft
        let showsIcon = cylShowsIcon
        let showsTitle = cylShowsTitle
        let accessorySpacing = (accessoryInline && (showsIcon || showsTitle)) ? spacing : 0
        var content = rect
        if accessoryInline {
            let leading = accessoryPlacement == .leading
            let reserved = accessorySize.width + accessorySpacing
            content.size.width = max(0, content.width - reserved)
            if leading != rtl { content.origin.x += reserved }
        }
        let icon = currentIconSize
        let gap = (showsIcon && showsTitle) ? spacing : 0
        let titleLimit = axis == .horizontal ? max(0, content.width - icon.width - gap) : content.width
        var titleSize = showsTitle ? titleLabel.sizeThatFits(CGSize(width: titleLimit, height: content.height)) : .zero
        titleSize.width = min(ceil(titleSize.width), titleLimit)
        if showsTitle { titleSize.width = min(max(titleSize.width, countdownTitleWidth), titleLimit) }
        titleSize.height = min(ceil(titleSize.height), content.height)
        let leadingAligned = alignment == .leading
        let iconFrame: CGRect
        let titleFrame: CGRect
        if axis == .horizontal {
            let group = icon.width + gap + titleSize.width
            let start = leadingAligned ? 0 : floor((content.width - group) / 2)
            let iconX = rtl ? content.maxX - start - icon.width : content.minX + start
            let titleX = rtl ? iconX - gap - titleSize.width : iconX + icon.width + gap
            iconFrame = CGRect(x: iconX, y: content.midY - icon.height / 2, width: icon.width, height: icon.height)
            titleFrame = CGRect(x: titleX, y: content.midY - titleSize.height / 2, width: titleSize.width, height: titleSize.height)
        } else {
            let group = icon.height + gap + titleSize.height
            let top = content.minY + floor((content.height - group) / 2)
            let iconX = Self.cylStackedX(width: icon.width, in: content, leadingAligned: leadingAligned, rtl: rtl)
            let titleX = Self.cylStackedX(width: titleSize.width, in: content, leadingAligned: leadingAligned, rtl: rtl)
            iconFrame = CGRect(x: iconX, y: top, width: icon.width, height: icon.height)
            titleFrame = CGRect(x: titleX, y: top + icon.height + gap, width: titleSize.width, height: titleSize.height)
        }
        imageView.frame = iconFrame
        animationView?.frame = iconFrame
        // [EN] The appearance's title offset (`titlePositionAdjustment`). [CN] 外观的标题偏移（`titlePositionAdjustment`）。
        let offset = currentItemStateAppearance?.titlePositionAdjustment ?? .zero
        titleLabel.frame = titleFrame.offsetBy(dx: offset.horizontal, dy: offset.vertical)
        layoutAccessory(in: rect, iconFrame: iconFrame, rightToLeft: rtl)
    }

    private func layoutAccessory(in rect: CGRect, iconFrame: CGRect, rightToLeft rtl: Bool) {
        guard let accessory = accessoryView else { return }
        let size = accessorySize
        let midY = rect.midY - size.height / 2
        switch accessoryPlacement {
        case .leading:
            accessory.frame = CGRect(x: rtl ? rect.maxX - size.width : rect.minX, y: midY, width: size.width, height: size.height)
        case .trailing:
            accessory.frame = CGRect(x: rtl ? rect.minX : rect.maxX - size.width, y: midY, width: size.width, height: size.height)
        case .topTrailing:
            let x = rtl ? iconFrame.minX - size.width / 2 : iconFrame.maxX - size.width / 2
            accessory.frame = CGRect(x: x, y: max(0, iconFrame.minY - size.height / 2), width: size.width, height: size.height)
        }
    }

    // MARK: - State 状态

    open override var isSelected: Bool {
        didSet {
            guard isSelected != oldValue else { return }
            applyItemAppearance()
            updateIcon()
            itemStateDidChange()
            updateItemAccessibility()
        }
    }

    open override var isHighlighted: Bool {
        didSet {
            guard isHighlighted != oldValue else { return }
            applyCountdownAppearance()
            itemStateDidChange()
        }
    }

    open override var isEnabled: Bool {
        didSet {
            guard isEnabled != oldValue else { return }
            applyItemAppearance()
            applyCountdownAppearance()
            itemStateDidChange()
            updateItemAccessibility()
        }
    }

    /**
     [EN] Subclass hook: called when selected, highlighted or enabled changes; update colors, backgrounds and borders.
     [CN] 子类钩子：选中、高亮或可用状态变化时调用；在这里更新颜色、背景与边框。
     */
    open func itemStateDidChange() {
        // [EN] Subclass hook; nothing by default. [CN] 子类钩子；默认不做任何事。
    }

    // MARK: - Appearance 外观

    /**
     [EN] Tints the icon: `imageView.tintColor`, and the animation view when it takes a tint (`-cyl_applyAnimationViewTintColor:`,
          called by selector). Called with the current state's `iconColor`; a subclass with its own default colors calls it too.
     [CN] 为图标着色：`imageView.tintColor`，以及接受着色的动画视图（通过 selector 调用 `-cyl_applyAnimationViewTintColor:`）。以当前状态的
          `iconColor` 调用；有自己默认颜色的子类也可以调用。
     */
    @objc(applyIconTintColor:)
    open func applyIconTintColor(_ color: UIColor?) {
        lastIconTintColor = color
        imageView.tintColor = color
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        // [EN] By selector: the tint method is declared by the tab bar's animation subspec, which this component does not import.
        // [CN] 通过 selector 调用：着色方法声明在 TabBar 的动画子库中，本组件不导入它。
        // [EN] With the state when the view takes it: a fixed tint only on the unselected item (2026-11-19).
        // [CN] 视图支持时带上状态：固定着色只用于未选中的 item（2026-11-19）。
        let tintWithState = NSSelectorFromString("cyl_applyAnimationViewTintColor:selected:")
        let tint = NSSelectorFromString("cyl_applyAnimationViewTintColor:")
        if let view = animationView, view.responds(to: tintWithState) {
            typealias CYLTintWithState = @convention(c) (AnyObject, Selector, UIColor?, Bool) -> Void
            let implementation = unsafeBitCast(view.method(for: tintWithState), to: CYLTintWithState.self)
            implementation(view, tintWithState, color, isSelected)
        } else if let view = animationView, view.responds(to: tint) {
            _ = view.perform(tint, with: color)
        }
        #endif
    }

    /**
     [EN] Applies `itemAppearance` for the current state; called on state, appearance and trait changes and when the
          animation view loads.
     [CN] 按当前状态应用 `itemAppearance`；在状态、外观与 trait 变化以及动画视图加载时调用。
     */
    open func applyItemAppearance() {
        guard let state = currentItemStateAppearance else { return }
        if let color = state.iconColor { applyIconTintColor(color) }
        let attributes = state.titleTextAttributes
        if let font = attributes[.font] as? UIFont { titleLabel.font = font }
        if let color = attributes[.foregroundColor] as? UIColor { titleLabel.textColor = color }
        setNeedsLayout()
    }

    open override func traitCollectionDidChange(_ previousTraitCollection: UITraitCollection?) {
        super.traitCollectionDidChange(previousTraitCollection)
        // [EN] A dynamic icon color is resolved again for the animation view's tint. [CN] 动态图标颜色为动画视图的着色重新解析。
        if traitCollection.hasDifferentColorAppearance(comparedTo: previousTraitCollection) {
            applyItemAppearance()
            if currentItemStateAppearance?.iconColor == nil, let color = lastIconTintColor {
                applyIconTintColor(color)
            }
        }
    }

    // MARK: - Animation 动画

    /**
     [EN] Builds the animation view for `animationURL` again (after a source, a size or a file change).
     [CN] 重新为 `animationURL` 创建动画视图（来源、尺寸或文件变化后）。
     */
    open func reloadAnimation() {
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        stopLoopTimer()
        detachEndHandler()
        storedAnimationView?.removeFromSuperview()
        storedAnimationView = nil
        playing = false
        isShowingImageAfterAnimationEnd = false
        if let url = animationURL, !cylAnimatedItemLocalFileIsMissing(url) {
            let size = (iconSize.width > 0 && iconSize.height > 0)
                ? iconSize : CGSize(width: cylAnimatedItemDefaultAnimationSide, height: cylAnimatedItemDefaultAnimationSide)
            if let view = animationSource.animationView(url: url, size: size, contentMode: .scaleAspectFit) {
                view.isUserInteractionEnabled = false
                view.isAccessibilityElement = false
                view.accessibilityElementsHidden = true
                insertSubview(view, aboveSubview: imageView)
                storedAnimationView = view
                attachEndHandler()
                applyPlayerSettings()
                if drivesAnimationPlayback { setPlayerValue(animationRestingProgress, for: "progress") }
                // [EN] A local file is in place now; a download reports through `cylAnimationViewDidLoad`.
                // [CN] 本地文件此时已就绪；下载中的文件通过 `cylAnimationViewDidLoad` 报告。
                if !CYLTabBarItemAnimationIsLoading(view) { notifyAnimationLoaded(of: view) }
            } else {
                // [EN] Debug builds: a type whose engine is not in the build says which pod to add. [CN] debug 构建：引擎未参与构建的类型提示需要加入的 pod。
                CYLAnimationWarnMissingEngine(nil, url)
                notifyAnimationFailed()
            }
        } else if animationURL != nil {
            notifyAnimationFailed()
        }
        #else
        // [EN] No engine: debug builds say which pod to add. [CN] 没有引擎：debug 构建提示需要加入的 pod。
        if let url = animationURL { CYLAnimationWarnMissingEngine(nil, url); notifyAnimationFailed() }
        #endif
        updateIcon()
        contentDidChange()
    }

    /// [EN] `onAnimationLoaded` on the next main queue turn, so a host that sets the callback after the URL still hears it; only
    ///      while `view` is still the animation. [CN] 在下一次主队列循环调用 `onAnimationLoaded`，宿主在设置 URL 之后才设置回调也能收到；仅当 `view` 仍是当前动画。
    private func notifyAnimationLoaded(of view: UIView) {
        DispatchQueue.main.async { [weak self, weak view] in
            guard let self, let view, view === self.storedAnimationView else { return }
            self.onAnimationLoaded?()
        }
    }

    /// [EN] `onAnimationFailed` on the next main queue turn, for the same reason. [CN] 同理，在下一次主队列循环调用 `onAnimationFailed`。
    private func notifyAnimationFailed() {
        DispatchQueue.main.async { [weak self] in self?.onAnimationFailed?() }
    }

    /** [EN] Plays from the current progress. [CN] 从当前进度开始播放。 */
    open func playAnimation() {
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        guard let player = animationPlayer else { playAnimatedImage(); return }
        showAnimationAgain()
        playing = true
        applyPlayerSettings()
        player.play()
        startLoopTimerIfNeeded()
        postAnimationEvent("cyl.animation.didStart")
        #else
        playAnimatedImage()
        #endif
    }

    /**
     [EN] Pauses a playing animation where it is (speed 0, loop timer off) and posts `cyl.animation.didPause`; does nothing
          when nothing plays or it is already paused. Used while the user scrolls (docs/Lifecycle-Library.md).
     [CN] 在当前位置暂停正在播放的动画（速度 0，关闭循环定时器）并发出 `cyl.animation.didPause`；未播放或已暂停时不做任何事。
          用户滚动期间使用（docs/Lifecycle-Library.md）。
     */
    open func pauseAnimation() {
        // [EN] A GIF icon (animated image): the frames stop and the icon shows its still frame; resume plays them again.
        // [CN] GIF 图标（动图）：帧动画停止并显示静止帧；恢复时重新播放。
        if imageView.isAnimating, !pausedByScroll {
            pausedByScroll = true
            pausedAnimatedImage = true
            imageView.stopAnimating()
            postAnimationEvent("cyl.animation.didPause")
            return
        }
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        guard playing, !pausedByScroll, let player = animationPlayer as? NSObject else { return }
        pausedByScroll = true
        // [EN] `animationSpeed` is an optional protocol requirement: read and set it by key. [CN] `animationSpeed` 是可选协议要求：按 key 读取与设置。
        speedBeforePause = player.responds(to: NSSelectorFromString("animationSpeed"))
            ? ((player.value(forKey: "animationSpeed") as? CGFloat) ?? animationSpeed) : animationSpeed
        setPlayerValue(CGFloat(0), for: "animationSpeed")
        stopLoopTimer()
        postAnimationEvent("cyl.animation.didPause")
        #endif
    }

    /** [EN] Continues after `pauseAnimation()` and posts `cyl.animation.didResume`. [CN] 在 `pauseAnimation()` 之后继续播放并发出 `cyl.animation.didResume`。 */
    open func resumeAnimation() {
        if pausedAnimatedImage, pausedByScroll {
            pausedByScroll = false
            pausedAnimatedImage = false
            imageView.startAnimating()
            postAnimationEvent("cyl.animation.didResume")
            return
        }
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        guard pausedByScroll, animationPlayer != nil else { return }
        pausedByScroll = false
        setPlayerValue(speedBeforePause, for: "animationSpeed")
        startLoopTimerIfNeeded()
        postAnimationEvent("cyl.animation.didResume")
        #endif
    }

    /** [EN] Plays from progress 0 (the examples' "Play all"). [CN] 从进度 0 开始播放（示例中的「全部播放」）。 */
    open func restartAnimation() {
        animationRestartToken += 1
        if animationView == nil, playAnimatedImage() { return }
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        setPlayerValue(CGFloat(0), for: "progress")
        playAnimation()
        #endif
    }

    /** [EN] Stops and shows the resting progress. [CN] 停止并显示静止进度。 */
    open func stopAnimation() {
        stopAnimatedImage()
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        let player = animationPlayer
        let wasPlaying = playing
        playing = false
        showAnimationAgain()
        stopLoopTimer()
        player?.stop()
        if drivesAnimationPlayback { setPlayerValue(animationRestingProgress, for: "progress") }
        if wasPlaying { postAnimationEvent("cyl.animation.didStop") }
        #endif
    }

    /**
     [EN] Posts an animation moment (`cyl.animation.didStart` / `didStop`) as a `NotificationCenter` notification whose object is
          this view: the animation pod does not depend on CYLDeallocBlockExecutor, CYLTabBarController bridges the
          notification into the library (CYLAnimationEventBridge), so observers hear it as a lifecycle event.
     [CN] 以 `NotificationCenter` 通知发出动画时机（`cyl.animation.didStart` / `didStop`），object 为本视图：动画 pod 不依赖
          CYLDeallocBlockExecutor，由 CYLTabBarController 桥接进库（CYLAnimationEventBridge），观察者即可作为生命周期事件收到。
     */
    private func postAnimationEvent(_ name: String) {
        NotificationCenter.default.post(name: Notification.Name(name), object: self, userInfo: ["url": animationURL as Any])
    }

    /** [EN] Shows the last frame without playing. [CN] 不播放，直接显示最后一帧。 */
    open func showAnimationLastFrame() {
        #if CYL_ANIMATION_ENGINE_AVAILABLE
        playing = false
        showAnimationAgain()
        stopLoopTimer()
        animationPlayer?.showLastFrame()
        #endif
    }

    /// [EN] Shows the animation again in place of the still image shown after its end. [CN] 重新显示动画，替换结束后显示的静态图片。
    private func showAnimationAgain() {
        guard isShowingImageAfterAnimationEnd else { return }
        isShowingImageAfterAnimationEnd = false
        updateIcon()
        setNeedsLayout()
    }

    private func stopLoopTimer() {
        loopTimer?.invalidate()
        loopTimer = nil
    }

    #if CYL_ANIMATION_ENGINE_AVAILABLE
    /// [EN] Sets an optional player property (`progress`, `animationSpeed`, `loops`) when the player has it. Swift cannot assign
    ///      an optional protocol requirement, so it goes through its setter by key.
    /// [CN] 播放器有该可选属性（`progress`、`animationSpeed`、`loops`）时设置它。Swift 不能给可选协议要求赋值，因此按 key 调用其 setter。
    private func setPlayerValue(_ value: Any, for key: String) {
        guard let player = animationPlayer as? NSObject else { return }
        let setter = NSSelectorFromString("set" + key.prefix(1).uppercased() + key.dropFirst() + ":")
        if player.responds(to: setter) { player.setValue(value, forKey: key) }
    }

    /// [EN] Gives the player's `onEnded` to the view (a player without it never reports an end). The block holds the view
    ///      weakly: the player belongs to the animation view, which the view owns.
    /// [CN] 把播放器的 `onEnded` 交给视图（没有它的播放器从不报告结束）。block 对视图是弱引用：播放器属于动画视图，而动画视图由本视图持有。
    private func attachEndHandler() {
        guard let player = animationPlayer as? NSObject, player.responds(to: NSSelectorFromString("setOnEnded:")) else { return }
        let handler: @convention(block) () -> Void = { [weak self] in self?.animationPassDidEnd() }
        player.setValue(unsafeBitCast(handler, to: AnyObject.self), forKey: "onEnded")
    }

    private func detachEndHandler() {
        guard let player = animationPlayer as? NSObject, player.responds(to: NSSelectorFromString("setOnEnded:")) else { return }
        player.setValue(nil, forKey: "onEnded")
    }

    /// [EN] A pass ended. While the view loops the animation (itself or by the loop restart) there is no end to report.
    /// [CN] 一遍播放结束。视图在让动画循环时（自己循环或由循环重播实现）没有可报告的结束。
    private func animationPassDidEnd() {
        if drivesAnimationPlayback, animationLoops { return }
        playing = false
        stopLoopTimer()
        if showsImageWhenAnimationEnds, animationView != nil {
            isShowingImageAfterAnimationEnd = true
            updateIcon()
            setNeedsLayout()
        }
        onAnimationEnd?()
    }

    private func applyPlayerSettings() {
        guard drivesAnimationPlayback, animationPlayer != nil else { return }
        if animationSpeed > 0 { setPlayerValue(animationSpeed, for: "animationSpeed") }
        setPlayerValue(animationLoops, for: "loops")
    }

    /// [EN] A player without `loops` (or with a `loops` it ignores) is restarted when it reaches the end, as
    ///      CollectionViewClassifyMenu's tags did.
    /// [CN] 没有 `loops`（或忽略 `loops`）的播放器，在播放到末尾时重新开始，与 CollectionViewClassifyMenu 的标签做法一致。
    private func startLoopTimerIfNeeded() {
        guard drivesAnimationPlayback, animationLoops, loopTimer == nil, let player = animationPlayer,
              !player.responds(to: #selector(setter: CYLTabBarItemAnimationPlayer.loops)),
              player.responds(to: #selector(getter: CYLTabBarItemAnimationPlayer.progress)) else { return }
        let timer = Timer(timeInterval: cylAnimatedItemLoopCheckInterval, repeats: true) { [weak self] timer in
            guard let self = self, self.playing, let current = self.animationPlayer else {
                timer.invalidate()
                return
            }
            if (current.progress ?? 0) >= 0.999 {
                self.setPlayerValue(CGFloat(0), for: "progress")
                current.play()
            }
        }
        loopTimer = timer
        RunLoop.main.add(timer, forMode: .common)
    }
    #endif

    // MARK: - Gesture handling 手势处理

    @objc(cyl_handleTap) private func handleTap() {
        delegate?.animatedItemViewDidTap?(self)
        if itemStyle == .countdown, startsCountdownOnTap, countdownState != .running {
            startCountdown()
        }
    }

    @objc(cyl_handleAccessoryTap) private func handleAccessoryTap() {
        delegate?.animatedItemViewDidTapAccessory?(self)
    }

    @objc(cyl_handleLongPress:) private func handleLongPress(_ recognizer: UILongPressGestureRecognizer) {
        if recognizer.state == .began { delegate?.animatedItemViewDidLongPress?(self) }
    }

    @objc(cyl_handlePan:) private func handlePan(_ recognizer: UIPanGestureRecognizer) {
        let translation = recognizer.translation(in: superview)
        switch recognizer.state {
        case .began:
            delegate?.animatedItemViewDidBeginDrag?(self)
        case .changed:
            if dragMovesView { transform = CGAffineTransform(translationX: translation.x, y: translation.y) }
            delegate?.animatedItemView?(self, didDragWithTranslation: translation)
        case .ended, .cancelled, .failed:
            let cancelled = recognizer.state != .ended
            if dragMovesView {
                UIView.animate(withDuration: UIAccessibility.isReduceMotionEnabled ? 0 : 0.2) {
                    self.transform = .identity
                }
            }
            delegate?.animatedItemView?(self, didEndDragWithTranslation: translation, cancelled: cancelled)
        default:
            break
        }
    }

    open override func gestureRecognizerShouldBegin(_ gestureRecognizer: UIGestureRecognizer) -> Bool {
        if gestureRecognizer === panGestureRecognizer {
            guard isDragEnabled else { return false }
            return delegate?.animatedItemViewShouldBeginDrag?(self) ?? true
        }
        if gestureRecognizer === longPressGestureRecognizer {
            return delegate?.responds(to: #selector(CYLAnimatedItemViewDelegate.animatedItemViewDidLongPress(_:))) ?? false
        }
        return super.gestureRecognizerShouldBegin(gestureRecognizer)
    }

    // MARK: - Countdown 倒计时

    private var cylNow: Date { countdownDateProvider?() ?? Date() }

    private func countdownStyleDidChange(from oldStyle: CYLAnimatedItemStyle) {
        guard itemStyle != oldStyle else { return }
        if itemStyle == .countdown {
            // [EN] The default look of a countdown button: a rounded border and a light background, as the original
            //      SMSCodeButton. Set these properties again after the style to change them.
            // [CN] 倒计时按钮的默认外观：圆角边框与浅色背景，与最初的 SMSCodeButton 一致。要修改，请在设置样式之后再设置这些属性。
            if contentInsets == .zero { contentInsets = UIEdgeInsets(top: 8, left: 12, bottom: 8, right: 12) }
            if backgroundColor == nil { backgroundColor = .secondarySystemBackground }
            layer.cornerRadius = 6
            layer.masksToBounds = true
            titleLabel.font = UIFont.preferredFont(forTextStyle: .body)
            showCountdownIdleOrFinishedTitle()
            applyCountdownAppearance()
            restoreCountdownFromCache()
        } else {
            resetCountdown()
            layer.cornerRadius = 0
            layer.borderWidth = 0
            titleLabel.alpha = 1
            imageView.alpha = 1
        }
        contentDidChange()
    }

    /// [EN] Shows the title that belongs to the current state, after a title property changed. [CN] 某个标题属性变化后，显示与当前状态对应的标题。
    private func refreshCountdownTitle() {
        guard itemStyle == .countdown else { return }
        if countdownState == .running {
            title = cylAnimatedItemCountdownText(countdownRunningTitleFormat, seconds: max(countdownShownSeconds, 0))
        } else {
            showCountdownIdleOrFinishedTitle()
        }
    }

    private func showCountdownIdleOrFinishedTitle() {
        title = countdownState == .finished ? countdownFinishedTitle : countdownIdleTitle
    }

    /// [EN] The widest title the countdown shows, so the control keeps its width: the idle and finished titles and the
    ///      running one with the widest digits of `countdownDuration`. 0 for another style.
    /// [CN] 倒计时会显示的最宽标题，使控件保持宽度：待机标题、结束标题，以及用 `countdownDuration` 位数的最宽数字组成的倒计时标题。其他样式为 0。
    private var countdownTitleWidth: CGFloat {
        guard itemStyle == .countdown else { return 0 }
        let digits = String(max(1, Int(ceil(countdownDuration)))).count
        let widest = Int(String(repeating: "8", count: digits)) ?? 88
        let attributes: [NSAttributedString.Key: Any] = [.font: titleLabel.font as Any]
        let texts = [countdownIdleTitle, countdownFinishedTitle, cylAnimatedItemCountdownText(countdownRunningTitleFormat, seconds: widest)]
        return texts.map { ceil(($0 as NSString).size(withAttributes: attributes).width) }.max() ?? 0
    }

    /// [EN] The border, the title color and the pressed look of the countdown style, for the state it is in.
    /// [CN] 倒计时样式在当前状态下的边框、标题颜色与按下外观。
    private func applyCountdownAppearance() {
        guard itemStyle == .countdown else { return }
        let running = countdownState == .running
        let border: UIColor = running ? .lightGray : (tintColor ?? .systemBlue)
        layer.borderColor = border.resolvedColor(with: traitCollection).cgColor
        layer.borderWidth = 1 / max(1, traitCollection.displayScale)
        if running { titleLabel.textColor = countdownRunningTitleColor }
        let alpha: CGFloat = isHighlighted ? 0.5 : 1
        titleLabel.alpha = alpha
        imageView.alpha = alpha
    }

    /// [EN] Puts back the title color the running color replaced. [CN] 恢复被倒计时颜色替换的标题颜色。
    private func restoreCountdownTitleColor() {
        guard let color = countdownRestingTitleColor else { return }
        titleLabel.textColor = color
        countdownRestingTitleColor = nil
    }

    /**
     [EN] Starts (or restarts) for `countdownDuration` seconds. Switches the style to countdown when it is not.
     [CN] 开始（或重新开始）`countdownDuration` 秒的倒计时。样式不是倒计时时会切换为倒计时样式。
     */
    open func startCountdown() {
        startCountdown(withDuration: countdownDuration)
    }

    /**
     [EN] Starts for `duration` seconds, e.g. the "retry after" the server sent. [CN] 开始 `duration` 秒的倒计时，例如服务器返回的「多少秒后重试」。
     */
    @objc(startCountdownWithDuration:)
    open func startCountdown(withDuration duration: TimeInterval) {
        guard duration > 0 else {
            resetCountdown()
            return
        }
        if itemStyle != .countdown { itemStyle = .countdown }
        let start = cylNow
        beginCountdown(start: start, end: start.addingTimeInterval(duration), duration: duration, announcesStart: true)
    }

    /// [EN] Enters the running state for `start`...`end`; `announcesStart` is false when a cached countdown is taken up again.
    /// [CN] 进入 `start`…`end` 的运行状态；接续缓存的倒计时时 `announcesStart` 为 false。
    private func beginCountdown(start: Date, end: Date, duration: TimeInterval, announcesStart: Bool) {
        if countdownState != .running {
            // [EN] The color to go back to when the time is up, taken before the running color replaces it.
            // [CN] 时间到之后要恢复的颜色，在倒计时颜色替换它之前取得。
            countdownRestingTitleColor = titleLabel.textColor
        }
        countdownRunDuration = duration
        countdownStartDate = start
        countdownEndDate = end
        countdownState = .running
        countdownShownSeconds = -1
        isEnabled = false
        saveCountdownToCache()
        startCountdownTimer()
        updateIcon()
        if announcesStart { delegate?.animatedItemViewDidStartCountdown?(self) }
        refreshCountdown()
        contentDidChange()
    }

    /**
     [EN] Stops and shows the idle title, with no finish callback. [CN] 停止并显示待机标题，不触发结束回调。
     */
    open func resetCountdown() {
        let wasRunning = countdownState == .running
        stopCountdownTimer()
        countdownEndDate = nil
        countdownStartDate = nil
        clearCountdownCache()
        countdownState = .idle
        if wasRunning {
            isEnabled = true
            restoreCountdownTitleColor()
        }
        if itemStyle == .countdown {
            showCountdownIdleOrFinishedTitle()
            applyCountdownAppearance()
        }
        updateIcon()
        contentDidChange()
    }

    /**
     [EN] Reads the clock now: a tick on demand, e.g. after the app returns (done by the control itself).
     [CN] 立即读取时钟：按需 tick，例如 App 返回前台后（控件自己会做）。
     */
    @objc open func refreshCountdown() {
        guard countdownState == .running, let start = countdownStartDate, let end = countdownEndDate else { return }
        let now = cylNow
        let left = end.timeIntervalSince(now)
        // [EN] Closed when the time is up, and also when the local clock is no longer plausible for this countdown: the clock
        //      was set back to before the start (a left time longer than the longest duration, which was recorded at the
        //      start). The control is then enabled again and a new countdown can start. A second of tolerance for clock sync.
        // [CN] 时间到时关闭；本地时钟对这次倒计时不再合理时也关闭：时钟被调回到开始之前（剩余时间超过开始时记录的最长时长）。
        //      此时控件恢复可用，可以重新开始倒计时。允许 1 秒的时钟同步误差。
        guard left > 0, now.timeIntervalSince(start) >= -1, left <= countdownRunDuration + 1 else {
            finishCountdown()
            return
        }
        let seconds = min(Int(ceil(left)), Int(ceil(countdownRunDuration)))
        guard seconds != countdownShownSeconds else { return }
        countdownShownSeconds = seconds
        title = cylAnimatedItemCountdownText(countdownRunningTitleFormat, seconds: seconds)
        applyCountdownAppearance()
        delegate?.animatedItemView?(self, didTickCountdown: seconds)
    }

    private func finishCountdown() {
        stopCountdownTimer()
        countdownEndDate = nil
        countdownStartDate = nil
        clearCountdownCache()
        countdownState = .finished
        isEnabled = true
        restoreCountdownTitleColor()
        showCountdownIdleOrFinishedTitle()
        applyCountdownAppearance()
        updateIcon()
        contentDidChange()
        if UIAccessibility.isVoiceOverRunning {
            UIAccessibility.post(notification: .announcement, argument: countdownFinishedTitle)
        }
        delegate?.animatedItemViewDidFinishCountdown?(self)
    }

    private static func countdownCacheName(_ key: String) -> String {
        "CYLAnimatedItemCountdown.\(key)"
    }

    /// [EN] Keeps the running countdown (start, end, longest duration) when `countdownCacheKey` is set.
    /// [CN] 设置了 `countdownCacheKey` 时保存运行中的倒计时（开始时间、结束时间、最长时长）。
    private func saveCountdownToCache() {
        guard let key = countdownCacheKey, let start = countdownStartDate, let end = countdownEndDate else { return }
        countdownCacheStore.set(["start": start.timeIntervalSince1970, "end": end.timeIntervalSince1970, "duration": countdownRunDuration],
                                forKey: Self.countdownCacheName(key))
    }

    private func clearCountdownCache() {
        guard let key = countdownCacheKey else { return }
        countdownCacheStore.removeObject(forKey: Self.countdownCacheName(key))
    }

    /// [EN] Takes up a cached countdown that is still valid by the local clock (not over, not from the future, not longer than
    ///      the longest duration it recorded); an invalid one is dropped, and the control stays idle. Nothing is announced.
    /// [CN] 接续按本地时钟仍然有效的缓存倒计时（未结束、不是来自未来、不超过其记录的最长时长）；无效的缓存被丢弃，控件保持待机。不触发开始回调。
    private func restoreCountdownFromCache() {
        guard itemStyle == .countdown, countdownState != .running, let key = countdownCacheKey,
              let cached = countdownCacheStore.dictionary(forKey: Self.countdownCacheName(key)) as? [String: TimeInterval],
              let start = cached["start"], let end = cached["end"], let duration = cached["duration"] else { return }
        let now = cylNow
        let startDate = Date(timeIntervalSince1970: start)
        let endDate = Date(timeIntervalSince1970: end)
        guard duration > 0, endDate.timeIntervalSince(now) > 0, now.timeIntervalSince(startDate) >= -1,
              endDate.timeIntervalSince(now) <= duration + 1 else {
            countdownCacheStore.removeObject(forKey: Self.countdownCacheName(key))
            return
        }
        beginCountdown(start: startDate, end: endDate, duration: duration, announcesStart: false)
    }

    /// [EN] The timer only schedules the reads; the end date decides. The app returning from the background reads the clock
    ///      at once, so the seconds spent there count (FIX: issue #1 of SMSCodeButton).
    /// [CN] 定时器只负责安排读取，由结束时间决定剩余时间。App 从后台返回时立即读取时钟，因此在后台度过的秒数会计入（修复 SMSCodeButton 的 issue #1）。
    private func startCountdownTimer() {
        stopCountdownTimer()
        let timer = Timer(timeInterval: cylAnimatedItemCountdownTickInterval, repeats: true) { [weak self] timer in
            guard let self = self else {
                timer.invalidate()
                return
            }
            self.refreshCountdown()
        }
        timer.tolerance = cylAnimatedItemCountdownTickInterval / 2
        RunLoop.main.add(timer, forMode: .common)
        countdownTimer = timer
        let center = NotificationCenter.default
        center.addObserver(self, selector: #selector(refreshCountdown), name: UIApplication.willEnterForegroundNotification, object: nil)
        center.addObserver(self, selector: #selector(refreshCountdown), name: UIApplication.didBecomeActiveNotification, object: nil)
    }

    private func stopCountdownTimer() {
        countdownTimer?.invalidate()
        countdownTimer = nil
        let center = NotificationCenter.default
        center.removeObserver(self, name: UIApplication.willEnterForegroundNotification, object: nil)
        center.removeObserver(self, name: UIApplication.didBecomeActiveNotification, object: nil)
    }

    // MARK: - Accessibility 无障碍

    /**
     [EN] Subclass hook: what VoiceOver reads (the title by default); add a badge, a count or a state. Call
          `updateItemAccessibility()` after a change the control cannot see.
     [CN] 子类钩子：VoiceOver 朗读的文本（默认为标题）；可以加入角标、数量或状态。控件无法感知的变化后调用 `updateItemAccessibility()`。
     */
    open func itemAccessibilityLabel() -> String? {
        (title ?? "").isEmpty ? nil : title
    }

    /** [EN] Refreshes `accessibilityLabel` from `itemAccessibilityLabel()`. [CN] 根据 `itemAccessibilityLabel()` 刷新 `accessibilityLabel`。 */
    open func updateItemAccessibility() {
        accessibilityLabel = itemAccessibilityLabel()
        var traits: UIAccessibilityTraits = .button
        if isSelected { traits.insert(.selected) }
        if !isEnabled { traits.insert(.notEnabled) }
        accessibilityTraits = traits
    }

    open override var accessibilityCustomActions: [UIAccessibilityCustomAction]? {
        get {
            let existing = super.accessibilityCustomActions
            guard let accessory = accessoryView, let label = accessory.accessibilityLabel, !label.isEmpty else { return existing }
            // [EN] VoiceOver reaches the accessory from the control's actions, since the control is one element.
            // [CN] 控件是一个无障碍元素，VoiceOver 通过控件的操作访问附加图标。
            let action = UIAccessibilityCustomAction(name: label, target: self, selector: #selector(performAccessoryAction(_:)))
            return (existing ?? []) + [action]
        }
        set { super.accessibilityCustomActions = newValue }
    }

    @objc(cyl_performAccessoryAction:) private func performAccessoryAction(_: UIAccessibilityCustomAction) -> Bool {
        handleAccessoryTap()
        return true
    }
}

#if CYL_ANIMATION_ENGINE_AVAILABLE
/**
 [EN] Told by the engine when the animation file loads or fails after the view was made.
 [CN] 动画文件在视图创建后加载完成或失败时由引擎通知。
 */
extension CYLAnimatedItemView: CYLTabBarItemAnimationFailureHandling {
    /** [EN] The file of a loading animation arrived: show the animation. [CN] 加载中的动画拿到了文件：显示动画。 */
    open func cylAnimationViewDidLoad(_ animationView: UIView) {
        guard animationView === self.animationView else { return }
        updateIcon()
        contentDidChange()
        onAnimationLoaded?()
    }

    /**
     [EN] A corrupted file, a parse error or a failed download: drop the animation; the static image or the placeholder shows.
     [CN] 文件损坏、解析错误或下载失败：移除动画，显示静态图片或占位图。
     */
    open func cylAnimationViewDidFail(_ animationView: UIView, error _: Error?) {
        guard animationView === self.animationView else { return }
        stopLoopTimer()
        detachEndHandler()
        animationView.removeFromSuperview()
        storedAnimationView = nil
        playing = false
        updateIcon()
        contentDidChange()
        onAnimationFailed?()
    }
}
#endif
